UPDATE accounts SET balance = balance - 100 WHERE id = 1;
-- crash! step two never runs:
-- UPDATE ... balance + 100 WHERE id = 2;
SELECT * FROM accounts;

BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
-- crash before COMMIT acts like:
ROLLBACK;
SELECT * FROM accounts;

UPDATE accounts SET balance = balance - 30
  WHERE id = 1 AND balance >= 30;
UPDATE accounts SET balance = balance - 20
  WHERE id = 1 AND balance >= 20;
SELECT balance FROM accounts;

BEGIN;
SELECT balance FROM accounts
  WHERE id = 1 FOR UPDATE;
-- compute: 100 - 30 = 70
UPDATE accounts SET balance = 70
  WHERE id = 1;
COMMIT;

-- A writes 70
UPDATE accounts SET balance = 70, version = 8
  WHERE id = 1 AND version = 7;
SELECT changes();
-- B writes 80
UPDATE accounts SET balance = 80, version = 8
  WHERE id = 1 AND version = 7;
SELECT changes();

-- B re-reads: balance 70, version 8
UPDATE accounts SET balance = 50, version = 9
  WHERE id = 1 AND version = 8;
SELECT changes();
SELECT balance, version FROM accounts;

